create table temp_table (
    id                          number
        generated by default on null as identity
    not null enable,
    rco_directory               varchar2(50 byte),
    facility_disp               varchar2(50 byte),
    facility_desc               varchar2(255 byte),
    bldg_disp                   varchar2(50 byte),
    bldg_desc                   varchar2(255 byte),
    nurse_unit_disp             varchar2(50 byte),
    nurse_unit_desc             varchar2(255 byte),
    nu_outbound_alias           varchar2(50 byte),
    encounter_org               varchar2(50 byte),
    aff_fac_pool_alias          varchar2(50 byte),
    cluster_                    varchar2(50 byte),
    patient_type                varchar2(50 byte),
    patient_type_alias          varchar2(50 byte),
    medical_service             varchar2(50 byte),
    op_prefix                   varchar2(32767 byte),
    aff_srvc_pool_alias         varchar2(50 byte),
    med_svc_alias               varchar2(50 byte),
    patient_service_code        varchar2(50 byte),
    patient_service_description varchar2(32767 byte),
    status                      varchar2(50 byte),
    added_dt                    date,
    inactive_dt                 varchar2(50 byte)
);

alter table temp_table add primary key ( id )
    using index enable;


